const params = $('Set params').first().json;
const cfg = $('Get Project Config').first().json;
const users = $('Find Automation Agent').first().json.users || [];
const autoId = String(cfg.automation_agent_id || (users.length && users[0].id ? users[0].id : ''));
const chatbotStatus = String(cfg.ticket_custom_status_chatbot_automated_id || '');
const from = new Date(params.created_from + 'T00:00:00Z').getTime();
const toEx = new Date(params.created_to_exclusive + 'T00:00:00Z').getTime();
let all = [];
for (const p of $('Fetch Tickets').all()) { all = all.concat((p.json && p.json.results) || []); }
const seen = new Set();
const uniq = [];
for (const t of all) { if (!seen.has(t.id)) { seen.add(t.id); uniq.push(t); } }
const inWindow = uniq.filter(t => { const ts = new Date(t.created_at).getTime(); return ts >= from && ts < toEx; });
const isAssignedAuto = t => autoId && String(t.assignee_id || '') === autoId;
const isChatbotAuto = t => chatbotStatus && String(t.custom_status_id || '') === chatbotStatus;
const exclAssignee = inWindow.filter(isAssignedAuto);
const exclChatbot = inWindow.filter(t => !isAssignedAuto(t) && isChatbotAuto(t));
let cand = inWindow.filter(t => !isAssignedAuto(t) && !isChatbotAuto(t));
cand.sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
if (Number(params.max_tickets) > 0) cand = cand.slice(0, Number(params.max_tickets));
const metaKeys = Object.keys(cfg).filter(k => /automation|agent|chatbot/i.test(k)).map(k => k + '=' + cfg[k]);
return cand.map((t, i) => {
  const cfs = (t.custom_fields || []).filter(f => f.value !== null && f.value !== '' && f.value !== false).map(f => f.id + '=' + f.value).join('|');
  const o = { id: t.id, created_at: t.created_at, updated_at: t.updated_at, status: t.status, subject: t.subject, requester_id: t.requester_id, assignee_id: t.assignee_id || null, channel: t.via && t.via.channel, tags: t.tags || [], cf: cfs, description: t.description ? String(t.description).slice(0, 1500) : '' };
  if (i === 0) { o._meta = { project_key: params.project_key, automation_user_id: autoId, automation_agent_id_from_config: cfg.automation_agent_id || null, email_lookup_id: users.length ? users[0].id : null, chatbot_status_id: chatbotStatus || null, zendesk_domain: cfg.zendesk_domain, raw_fetched: uniq.length, in_window: inWindow.length, excluded_automation_assignee: exclAssignee.length, excluded_chatbot_status: exclChatbot.length, candidates: cand.length, config_keys_matching: metaKeys }; }
  return { json: o };
});

const params = $('Set params').first().json;
const limit = Number(params.text_limit) || 450;
const withBodies = params.include_bodies === true || params.include_bodies === 'true';
const bucketFilter = Number(params.bucket_filter) || 0;
const tickets = $('Flatten Tickets').all();
const responses = $input.all();
const meta = tickets.length ? (tickets[0].json._meta || {}) : {};
const autoId = String(meta.automation_user_id || '');
function clean(s, cap) {
  if (!s) return '';
  const c = cap || limit;
  let t = String(s).replace(/\r/g, '');
  t = t.split('\n').filter(l => !/^\s*>/.test(l)).join(' ');
  t = t.replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  t = t.replace(/\s+/g, ' ').trim();
  return t.length > c ? t.slice(0, c) + '...' : t;
}
const rows = [];
const totals = { analyzed: 0, bucket1: 0, bucket2: 0, bucket3: 0, unresolved: 0, comment_fetch_errors: 0, nocat_notes: 0 };
for (let i = 0; i < tickets.length; i++) {
  const t = tickets[i].json;
  const resp = responses[i] ? responses[i].json : {};
  if (!resp || !resp.comments) totals.comment_fetch_errors++;
  const comments = (resp && resp.comments) || [];
  const pub = comments.filter(c => c.public);
  const cust = pub.filter(c => String(c.author_id) === String(t.requester_id));
  const auto = autoId ? pub.filter(c => String(c.author_id) === autoId) : [];
  const agent = pub.filter(c => String(c.author_id) !== String(t.requester_id) && (!autoId || String(c.author_id) !== autoId));
  const notes = comments.filter(c => !c.public);
  const rawNotes = notes.map(c => String(c.plain_body || c.body || '')).join(' \n ');
  const nocat = /did not fit into any of the predefined categories/i.test(rawNotes);
  const fr = rawNotes.match(/Fail reason:\s*([a-zA-Z_]+)/);
  if (nocat) totals.nocat_notes++;
  let bucket;
  if (auto.length > 0) { bucket = 3; } else if (agent.length <= 1) { bucket = 1; } else { bucket = 2; }
  totals.analyzed++;
  if (bucket === 1) { totals.bucket1++; } else if (bucket === 2) { totals.bucket2++; } else { totals.bucket3++; }
  if (t.status !== 'solved' && t.status !== 'closed') totals.unresolved++;
  const row = { id: t.id, d: String(t.created_at).slice(5, 10), st: t.status, b: bucket, ch: t.channel, subj: t.subject, nc: cust.length, na: agent.length, nb: auto.length, nn: notes.length, nocat: nocat, failreason: fr ? fr[1] : '', tags: (t.tags || []).join(','), cf: t.cf || '' };
  if (withBodies) {
    row.cust1 = clean((cust[0] && cust[0].plain_body) ? cust[0].plain_body : (t.description || ((pub[0] || {}).plain_body)), 1200);
    row.agent1 = agent[0] ? clean(agent[0].plain_body) : '';
    row.cust2 = cust[1] ? clean(cust[1].plain_body) : '';
    row.agentL = agent.length > 1 ? clean(agent[agent.length - 1].plain_body) : '';
    row.auto1 = auto[0] ? clean(auto[0].plain_body, 300) : '';
    row.notes_txt = clean(rawNotes, 700);
  }
  if (bucketFilter === 0 || bucketFilter === bucket) rows.push(row);
}
const off = Number(params.output_offset) || 0;
const lim = Number(params.output_limit) || 0;
const sliced = lim > 0 ? rows.slice(off, off + lim) : rows.slice(off);
return [{ json: { meta, window: { from: params.created_from, to_exclusive: params.created_to_exclusive }, totals, returned: sliced.length, matching_filter: rows.length, tickets: sliced } }];
